package com.fluxisai.catalog;

import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
import java.math.BigDecimal; import java.util.UUID; import com.fluxisai.common.error.ConflictException; import com.fluxisai.common.security.CurrentUser; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension;
@ExtendWith(MockitoExtension.class) class ProfessionalServiceServiceTest { static final UUID USER=UUID.fromString("11111111-1111-1111-1111-111111111111"); @Mock ProfessionalServiceRepository services; @Mock CurrentUser currentUser; @InjectMocks ProfessionalServiceService service; @Test void createsServiceWithDecimalRate(){when(currentUser.id()).thenReturn(USER);when(services.save(any())).thenAnswer(i->i.getArgument(0));var result=service.create(new ProfessionalServiceRequest("  Consultoría  ",null,"Tech",PricingModel.HOURLY,new BigDecimal("125.5000"),"EUR",true,null,null));assertEquals(new BigDecimal("125.5000"),result.rate());assertEquals("Consultoría",result.name());} @Test void rejectsDuplicateName(){when(currentUser.id()).thenReturn(USER);when(services.existsByUserIdAndNameIgnoreCase(USER,"Consultoría")).thenReturn(true);assertThrows(ConflictException.class,()->service.create(new ProfessionalServiceRequest("Consultoría",null,null,PricingModel.FIXED,new BigDecimal("10"),"EUR",true,null,null)));verify(services,never()).save(any());} }
